#[repr(C)]
pub struct CbRgb255 {
    pub r: u8,
    pub g: u8,
    pub b: u8,
}

fn cb_luminance(r: f32, g: f32, b: f32) -> f32 {
    let r = if r > 0.04045 {
        ((r + 0.055) / 1.055).powf(2.4)
    } else {
        r / 12.92
    };
    let g = if g > 0.04045 {
        ((g + 0.055) / 1.055).powf(2.4)
    } else {
        g / 12.92
    };
    let b = if b > 0.04045 {
        ((b + 0.055) / 1.055).powf(2.4)
    } else {
        b / 12.92
    };
    0.2126 * r + 0.7152 * g + 0.0722 * b
}

fn cb_contrast_ratio(ra: f32, ga: f32, ba: f32, rb: f32, gb: f32, bb: f32) -> f32 {
    let lum_a = cb_luminance(ra, ga, ba);
    let lum_b = cb_luminance(rb, gb, bb);
    let (high, low) = if lum_a >= lum_b {
        (lum_a, lum_b)
    } else {
        (lum_b, lum_a)
    };
    high / low
}

pub fn contrast_ratio(a: CbRgb255, b: CbRgb255) -> f32 {
    cb_contrast_ratio(
        a.r as f32 / 255.0,
        a.g as f32 / 255.0,
        a.b as f32 / 255.0,
        b.r as f32 / 255.0,
        b.g as f32 / 255.0,
        b.b as f32 / 255.0,
    )
}
